properties.script:
var ROOT = '/tmp/oie-load';
var cmd = sourceMap.get('cmd');

if (cmd == 'prepare') {
    // Repeating the 64-character unit 16 to 256 times spreads payloads over 1 kB to
    // 16 kB, so a run is a mix of sizes rather than a thousand identical messages.
    var run = sourceMap.get('run');
    var count = parseInt(sourceMap.get('count'), 10);
    deleteTree(new java.io.File(ROOT));
    var stage = ROOT + '/' + run + '-stage';
    new java.io.File(stage).mkdirs();
    new java.io.File(ROOT + '/' + run).mkdirs();

    var bytes = 0;
    var expected = new java.lang.StringBuilder();
    for (var i = 0; i < count; i++) {
        // Coerce to a JS string: HashUtil returns a java.lang.String, whose charAt
        // yields a char that parseInt would read as a character code, not a digit.
        var unit = '' + HashUtil.generate('oie-load-' + i);
        var blob = new java.lang.StringBuilder();
        for (var r = 0, reps = 16 + (i % 241); r < reps; r++) {
            blob.append(unit);
        }
        var content = 'seq=' + i + ';unit=' + unit + ';blob=<BLOB>' + blob.toString() + '</BLOB>';
        FileUtil.write(stage + '/msg-' + ('000000' + i).slice(-6) + '.txt', false, content);
        bytes += content.length;
        // The route must agree with the entry channel's routing step. Build the line
        // as a JS string: appending a JS number to a StringBuilder yields '0.0'.
        var route = parseInt(unit.charAt(63), 16) % 2 === 0 ? 'MLLP' : 'HTTP';
        expected.append(i + ',' + HashUtil.generate(content, 'UTF-8', 'SHA-256') + ',' + route + '\n');
    }
    return 'count=' + count + ';bytes=' + bytes + '\n' + expected.toString();
}

if (cmd == 'arm') {
    // One directory rename gives the run a crisp start edge: every file appears at
    // once instead of trickling in while we are timing.
    var run = sourceMap.get('run');
    var from = new java.io.File(ROOT + '/' + run + '-stage');
    var to = new java.io.File(ROOT + '/' + run);
    deleteTree(to);
    if (!from.renameTo(to)) {
        throw 'could not arm ' + run;
    }
    return 'armed';
}

if (cmd == 'clean') {
    deleteTree(new java.io.File(ROOT));
    return 'cleaned';
}

if (cmd == 'stats') {
    // The JMX beans are instances of non-exported impl classes, which Rhino cannot
    // reflect on directly. Going through the exported interface's Method does work,
    // because the access check is made against the interface we looked it up on.
    var mf = java.lang.management.ManagementFactory;
    var noTypes = java.lang.reflect.Array.newInstance(java.lang.Class, 0);
    var noArgs = java.lang.reflect.Array.newInstance(java.lang.Object, 0);

    var cpu = -1;
    try {
        var osType = java.lang.Class.forName('com.sun.management.OperatingSystemMXBean');
        var os = mf.getPlatformMXBean(osType);
        if (os != null) {
            cpu = osType.getMethod('getProcessCpuTime', noTypes).invoke(os, noArgs).longValue();
        }
    } catch (e) {
        cpu = -1;
    }

    var gcCount = 0, gcMillis = 0;
    try {
        var gcType = java.lang.Class.forName('java.lang.management.GarbageCollectorMXBean');
        var countOf = gcType.getMethod('getCollectionCount', noTypes);
        var timeOf = gcType.getMethod('getCollectionTime', noTypes);
        var beans = mf.getPlatformMXBeans(gcType);
        for (var b = 0; b < beans.size(); b++) {
            gcCount += countOf.invoke(beans.get(b), noArgs).longValue();
            gcMillis += timeOf.invoke(beans.get(b), noArgs).longValue();
        }
    } catch (e) {
        gcCount = -1;
        gcMillis = -1;
    }

    var runtime = java.lang.Runtime.getRuntime();
    return 'cpuNanos=' + cpu
            + ';heapUsed=' + (runtime.totalMemory() - runtime.freeMemory())
            + ';gcCount=' + gcCount
            + ';gcMillis=' + gcMillis
            + ';threads=' + java.lang.Thread.activeCount();
}

throw 'unknown cmd: ' + cmd;

function deleteTree(file) {
    if (!file.exists()) {
        return;
    }
    var children = file.listFiles();
    if (children != null) {
        for (var i = 0; i < children.length; i++) {
            deleteTree(children[i]);
        }
    }
    file['delete']();
}
